export default "/* =========================================================================\n   DeepSeek Harness · Cherry Studio V2 毛玻璃主题适配（v0.6）\n   （由 cherry-studio-v2-glass-theme.css 适配而来）\n\n   v0.6（桌面端支持）：\n     · dsh-desktop（Electron shell，win32/darwin）下 fork 的 base.css 会把\n       body 背景清成 transparent（background 简写），导致背景图不可见、\n       只剩 acrylic 毛玻璃。新增 html[data-dsh-desktop='true'] body 规则\n       以同等特异性后注入，重新铺上背景图，桌面与 Web 观感一致。\n\n   适配要点（Cherry V2 → DSH）：\n     · 主题选择器：:root / .dark        →  html body / html body[data-ds-dark-theme]\n     · shadcn 变量（--background 等）    →  DSH 设计令牌（--dsw-alias-* / --dsw-specific-*，\n                                           定义见 packages/client/ui-theme design-platform.css）\n     · 结构选择器（data-ui / 类名）      →  DSH 稳定 data-* 接缝 + :has() 几何定位：\n                                          [data-conversation-scroll]（消息滚动区）、\n                                          [data-composer-seat]（输入栏容器）、\n                                          [data-composer-card]（输入胶囊）、\n                                          [data-chat-flow-kind]（消息节点行）、\n                                          div:has(> [data-slot='sidebar'|'details'])（三栏）\n     · 亮/暗两套值全部由 body 令牌覆写，跟随 DSH 外观设置（浅色/深色/跟随系统）自动切换。\n     · 选择器统一加 html 前缀（令牌声明），保证优先级高于内置令牌、与加载顺序无关。\n\n   v0.5（彻底移除侧边栏/详情栏 blur，勿回退）：\n     · 侧边栏/详情栏子树内不再使用任何 backdrop-filter。v0.3 曾把 blur 移到\n       ::before 伪元素上规避包含块问题，但重启后设置弹层依旧被挤进侧边栏窄框\n       ——实测表明伪元素上的 backdrop-filter 同样会使原元素成为 position:fixed\n       后代的包含块。毛玻璃观感改为：半透明填充（--dsw-specific-sidebar-fill）\n       + 渐变/色调叠加（无 blur），与不支持 backdrop-filter 的浏览器观感一致，\n       任何加载方式（HMR 或整页刷新）都不会破坏 fixed 弹层（设置/Modal 等）。\n     · 输入胶囊 [data-composer-card] 的磨砂保留：其内部无 fixed 后代（灯箱与\n       拖拽遮罩渲染在卡片之外），聚焦光环不受影响。\n\n   v0.4（气泡装饰移除）：\n     · 移除用户/steering 气泡结构装饰（描边、装饰线、磨砂、投影）。原因：结构\n       选择器下探层级不足，命中的是\"用户栈\"长方形容器而非气泡胶囊，产生违和\n       的长方形毛玻璃边框。仅保留 DSH 原生半透明胶囊（--dsw-specific-bubble）。\n\n   v0.3 修复（保留）：\n     · 消息滚动区 [data-conversation-scroll] 与输入容器 [data-composer-seat]\n       不施加 backdrop-filter：图片灯箱 ImageLightbox 与拖拽遮罩 DropOverlay\n       都是 fixed 定位且渲染在这些容器内部。同时主对话页背景图保持清晰。\n     · 透明度分层：主对话页表面高度透明（清晰背景图）；设置面板/弹窗/菜单等\n       浮层表面接近不透明（不影响其他窗口的阅读与操作）。\n\n   v0.2 保留（输入胶囊 Cherry 特征）：\n     · 输入胶囊：:focus-within 主题色描边 + 外发光光环（保留 --dsw-shadow-lv2）。\n\n   生效方式（dsh-cherry-glass 插件）：注入 <style data-plugin=\"dsh-cherry-glass\">，\n   随 client fiber 卸载时移除。构建后由 client-hmr 热替换：无需重启/刷新。\n   ========================================================================= */\n\n/* -------------------------------------------------------------------------\n   亮色主题（默认）\n   ------------------------------------------------------------------------- */\nhtml body {\n    /* --- 背景图与遮罩（亮色，低遮罩保证主对话页背景图清晰） --- */\n    --cherry-glass-bg-image: url('https://pic1.imgdb.cn/item/67d544f988c538a9b5bec3c7.jpg');\n    --cherry-glass-overlay-start: rgba(245, 248, 250, 0.1);\n    --cherry-glass-overlay-end: rgba(235, 240, 242, 0.16);\n\n    /* --- 主表面分层：\n           bg-base / layer-1 = 主对话页等\"内容表面\"，高度透明，透出背景图；\n           layer-2 = 设置面板、Modal 等\"窗口表面\"，接近不透明；\n           layer-3 / menu / overlay = 卡片、菜单、弹层，较不透明。 --- */\n    --dsw-alias-bg-base: rgba(255, 255, 255, 0.14);\n    --dsw-alias-bg-layer-1: rgba(250, 252, 253, 0.72);\n    --dsw-alias-bg-layer-2: rgba(250, 252, 253, 0.97);\n    --dsw-alias-bg-layer-3: rgba(251, 253, 254, 0.92);\n    --dsw-alias-bg-overlay: rgba(251, 253, 254, 0.96);\n    --dsw-alias-bg-module-platform: rgba(248, 250, 252, 0.8);\n    --dsw-alias-bg-multi-select: rgba(248, 250, 252, 0.85);\n    --dsw-specific-menu: rgba(251, 253, 254, 0.94);\n    --dsw-specific-selector: rgba(248, 250, 252, 0.85);\n    --dsw-specific-tip: rgba(248, 250, 252, 0.8);\n    --dsw-specific-login-input: rgba(248, 250, 252, 0.7);\n\n    /* --- 侧边栏（浅色玻璃：半透明填充 + 渐变叠加，无 blur——见结构玻璃注释） --- */\n    --dsw-specific-sidebar-fill: rgba(245, 248, 250, 0.5);\n    --cherry-glass-sidebar-start: rgba(255, 255, 255, 0.45);\n    --cherry-glass-sidebar-end: rgba(255, 255, 255, 0.18);\n    --cherry-glass-sidebar-tint: rgba(59, 130, 246, 0.12);\n\n    /* --- 输入栏（胶囊磨砂，背景图清晰透出） --- */\n    --dsw-specific-input-major: rgba(252, 253, 255, 0.78);\n\n    /* --- 聊天气泡（半透明磨砂） --- */\n    --dsw-specific-bubble: rgba(214, 243, 214, 0.62);\n    --dsw-specific-bubble-highlight: rgba(219, 234, 254, 0.55);\n\n    /* --- 主题色（蓝，Cherry 同款） --- */\n    --dsw-alias-brand-primary: rgb(60, 130, 220);\n    --dsw-alias-brand-primary-new-colorprimary-new-color: rgb(60, 130, 220);\n    --dsw-alias-button-primary-fill: rgb(60, 130, 220);\n    --dsw-alias-button-primary-hover: rgb(52, 116, 200);\n    --dsw-alias-button-info-fill: rgb(60, 130, 220);\n    --dsw-alias-button-info-hover: rgb(52, 116, 200);\n    --dsw-alias-state-business-primary: rgb(60, 130, 220);\n    --dsw-alias-state-business-tertiary: rgba(60, 130, 220, 0.14);\n    --dsw-alias-interactive-bg-active: rgba(38, 49, 72, 0.08);\n    --dsw-alias-interactive-bg-hover-accent: rgba(60, 130, 220, 0.12);\n    --dsw-specific-sidebar-nav-item-active-accent: rgba(60, 130, 220, 0.14);\n\n    /* --- 边框 --- */\n    --dsw-alias-border-l1: rgba(0, 0, 0, 0.05);\n    --dsw-alias-border-l2: rgba(0, 0, 0, 0.1);\n    --dsw-alias-border-l2-darkmode-thin: rgba(0, 0, 0, 0.08);\n    --dsw-alias-border-l3: rgba(0, 0, 0, 0.14);\n    --dsw-alias-border-l4: rgba(0, 0, 0, 0.18);\n\n    /* --- 代码（半透明磨砂，透出背景图） --- */\n    --dsw-alias-markdown-code-block: rgba(242, 245, 248, 0.62);\n    --dsw-alias-markdown-code-block-banner: rgba(242, 245, 248, 0.62);\n    --dsw-alias-markdown-code-segment-selected: rgba(255, 255, 255, 0.6);\n    --dsw-alias-markdown-code-segment-unselected: rgba(238, 241, 244, 0.5);\n    --dsw-alias-markdown-inline-code: rgba(230, 230, 230, 0.62);\n    --dsw-alias-markdown-citation: rgba(230, 240, 250, 0.6);\n    --dsw-alias-markdown-placeholder: rgba(242, 244, 247, 0.6);\n    --dsw-alias-markdown-tag: rgba(238, 241, 244, 0.6);\n\n    /* --- 滚动条（蓝色半透明） --- */\n    --dsw-alias-scrollbar-bg-l1: rgba(60, 130, 220, 0.16);\n    --dsw-alias-scrollbar-bg-l2: rgba(60, 130, 220, 0.2);\n    --dsw-alias-scrollbar-hover-l1: rgba(60, 130, 220, 0.3);\n    --dsw-alias-scrollbar-hover-l2: rgba(60, 130, 220, 0.36);\n\n    /* --- 过渡（侧边栏 / 输入胶囊） --- */\n    --cherry-glass-transition-duration: 0.35s;\n    --cherry-glass-transition-easing: ease-in-out;\n}\n\n/* -------------------------------------------------------------------------\n   暗色主题\n   ------------------------------------------------------------------------- */\nhtml body[data-ds-dark-theme] {\n    /* --- 背景图与遮罩（暗色，带淡蓝磨砂质感，低遮罩保清晰） --- */\n    --cherry-glass-bg-image: url('https://pic1.imgdb.cn/item/67d55d0e88c538a9b5bec87f.png');\n    --cherry-glass-overlay-start: rgba(10, 75, 122, 0.12);\n    --cherry-glass-overlay-end: rgba(10, 75, 122, 0.2);\n\n    /* --- 主表面分层（同上：内容表面透明、窗口表面不透明） --- */\n    --dsw-alias-bg-base: rgba(18, 22, 28, 0.3);\n    --dsw-alias-bg-layer-1: rgba(30, 33, 39, 0.68);\n    --dsw-alias-bg-layer-2: rgba(32, 34, 40, 0.96);\n    --dsw-alias-bg-layer-3: rgba(34, 36, 42, 0.9);\n    --dsw-alias-bg-overlay: rgba(34, 36, 42, 0.96);\n    --dsw-alias-bg-module-platform: rgba(30, 33, 39, 0.75);\n    --dsw-alias-bg-multi-select: rgba(30, 32, 37, 0.85);\n    --dsw-specific-menu: rgba(34, 36, 42, 0.94);\n    --dsw-specific-selector: rgba(30, 32, 37, 0.85);\n    --dsw-specific-tip: rgba(30, 32, 37, 0.8);\n    --dsw-specific-login-input: rgba(28, 30, 35, 0.7);\n\n    /* --- 侧边栏（深色玻璃：半透明填充 + 渐变叠加，无 blur） --- */\n    --dsw-specific-sidebar-fill: rgba(26, 28, 33, 0.55);\n    --cherry-glass-sidebar-start: rgba(35, 38, 43, 0.45);\n    --cherry-glass-sidebar-end: rgba(20, 22, 26, 0.2);\n    --cherry-glass-sidebar-tint: rgba(70, 150, 230, 0.12);\n\n    /* --- 输入栏 --- */\n    --dsw-specific-input-major: rgba(40, 43, 49, 0.75);\n\n    /* --- 聊天气泡 --- */\n    --dsw-specific-bubble: rgba(60, 68, 84, 0.62);\n    --dsw-specific-bubble-highlight: rgba(48, 58, 76, 0.6);\n\n    /* --- 主题色 --- */\n    --dsw-alias-brand-primary: rgb(70, 150, 230);\n    --dsw-alias-brand-primary-new-colorprimary-new-color: rgb(70, 150, 230);\n    --dsw-alias-button-primary-fill: rgb(70, 150, 230);\n    --dsw-alias-button-primary-hover: rgb(92, 168, 242);\n    --dsw-alias-button-info-fill: rgb(70, 150, 230);\n    --dsw-alias-button-info-hover: rgb(92, 168, 242);\n    --dsw-alias-state-business-primary: rgb(70, 150, 230);\n    --dsw-alias-state-business-tertiary: rgba(70, 150, 230, 0.16);\n    --dsw-alias-interactive-bg-active: rgba(255, 255, 255, 0.1);\n    --dsw-alias-interactive-bg-hover-accent: rgba(70, 150, 230, 0.18);\n    --dsw-specific-sidebar-nav-item-active-accent: rgba(70, 150, 230, 0.18);\n\n    /* --- 边框 --- */\n    --dsw-alias-border-l1: rgba(255, 255, 255, 0.05);\n    --dsw-alias-border-l2: rgba(255, 255, 255, 0.1);\n    --dsw-alias-border-l2-darkmode-thin: rgba(255, 255, 255, 0.06);\n    --dsw-alias-border-l3: rgba(255, 255, 255, 0.14);\n    --dsw-alias-border-l4: rgba(255, 255, 255, 0.18);\n\n    /* --- 代码 --- */\n    --dsw-alias-markdown-code-block: rgba(40, 43, 50, 0.66);\n    --dsw-alias-markdown-code-block-banner: rgba(40, 43, 50, 0.66);\n    --dsw-alias-markdown-code-segment-selected: rgba(38, 41, 47, 0.6);\n    --dsw-alias-markdown-code-segment-unselected: rgba(32, 35, 41, 0.6);\n    --dsw-alias-markdown-inline-code: rgba(60, 65, 75, 0.66);\n    --dsw-alias-markdown-citation: rgba(48, 58, 76, 0.66);\n    --dsw-alias-markdown-placeholder: rgba(35, 38, 44, 0.6);\n    --dsw-alias-markdown-tag: rgba(35, 38, 44, 0.6);\n\n    /* --- 滚动条 --- */\n    --dsw-alias-scrollbar-bg-l1: rgba(70, 150, 230, 0.2);\n    --dsw-alias-scrollbar-bg-l2: rgba(70, 150, 230, 0.24);\n    --dsw-alias-scrollbar-hover-l1: rgba(70, 150, 230, 0.38);\n    --dsw-alias-scrollbar-hover-l2: rgba(70, 150, 230, 0.42);\n\n    /* --- 过渡（侧边栏 / 输入胶囊） --- */\n    --cherry-glass-transition-duration: 0.35s;\n    --cherry-glass-transition-easing: ease-in-out;\n}\n\n/* -------------------------------------------------------------------------\n   背景图（铺在 body 上，半透明主表面透出——主对话页可看到清晰背景图）\n   ------------------------------------------------------------------------- */\nhtml body {\n    background-image:\n        linear-gradient(var(--cherry-glass-overlay-start), var(--cherry-glass-overlay-end)),\n        var(--cherry-glass-bg-image);\n    background-repeat: no-repeat;\n    background-position: center 30%;\n    background-size: cover;\n    background-attachment: fixed;\n    /* 图片加载前/失败时的兜底底色 */\n    background-color: rgb(233, 242, 246);\n}\n\nhtml body[data-ds-dark-theme] {\n    background-color: rgb(18, 22, 28);\n}\n\n/* -------------------------------------------------------------------------\n   桌面端（dsh-desktop / Electron shell）适配（v0.6）：\n   桌面 fork 的 ui-theme base.css 在\n   html[data-dsh-desktop-platform='win32'|'darwin'] body 上写了\n   `background: transparent`（简写会同时清掉 background-image），特异性\n   (0,1,2) 高于主题的 `html body` (0,0,2)，导致桌面窗口里背景图被抹掉、\n   只剩半透明面板 + 原生 acrylic 的\"纯毛玻璃\"观感。这里用同等特异性\n   (0,1,2)、靠后注入的规则把背景图重新铺回 body，恢复与 Web 端一致的\n   外观（图片清晰透出、面板半透明）。\n   ------------------------------------------------------------------------- */\nhtml[data-dsh-desktop='true'] body {\n    background-image:\n        linear-gradient(var(--cherry-glass-overlay-start), var(--cherry-glass-overlay-end)),\n        var(--cherry-glass-bg-image);\n    background-repeat: no-repeat;\n    background-position: center 30%;\n    background-size: cover;\n    background-attachment: fixed;\n}\n\nhtml[data-dsh-desktop='true'] body:not([data-ds-dark-theme]) {\n    background-color: rgb(233, 242, 246);\n}\n\nhtml[data-dsh-desktop='true'] body[data-ds-dark-theme] {\n    background-color: rgb(18, 22, 28);\n}\n\n/* -------------------------------------------------------------------------\n   结构玻璃：三栏框架\n   侧边栏（AppFrame 第一列，通过 :has() 几何定位，不依赖哈希类名）\n\n   重要（v0.5，勿回退）：侧边栏/详情栏子树内【禁止任何 backdrop-filter】。\n   元素的 backdrop-filter 会使自身成为 position:fixed 后代的包含块，把全屏\n   设置弹层（ui-settings-general 的 .overlay，position:fixed; inset:0，渲染在\n   侧边栏列内部）挤进侧边栏窄框。v0.3 曾把 blur 移到 ::before 伪元素上，实测\n   重启后依旧复现——伪元素上的 backdrop-filter 同样触发该行为。因此毛玻璃\n   观感完全由半透明填充（--dsw-specific-sidebar-fill）+ 渐变/色调叠加实现，\n   与不支持 backdrop-filter 的浏览器观感一致，任何加载方式都不会破坏弹层。\n   ------------------------------------------------------------------------- */\ndiv:has(> [data-slot='sidebar']) {\n    position: relative;\n    background-color: var(--dsw-specific-sidebar-fill);\n    transition: background-color var(--cherry-glass-transition-duration) var(--cherry-glass-transition-easing);\n}\n\ndiv:has(> [data-slot='sidebar'])::before {\n    content: '';\n    position: absolute;\n    inset: 0;\n    z-index: -1;\n    background-image:\n        linear-gradient(180deg, var(--cherry-glass-sidebar-start) 0%, var(--cherry-glass-sidebar-end) 100%),\n        radial-gradient(120% 100% at 50% 0%, var(--cherry-glass-sidebar-tint) 0%, transparent 70%);\n    pointer-events: none;\n}\n\n/* 详情栏（轨迹等）：无 blur（理由同上），其内容表面自带 --dsw-alias-bg-layer-* 背景 */\n\n/* 聊天消息区：不加 backdrop-filter（灯箱 ImageLightbox 是 fixed 定位渲染在\n   聊天节点内；且模糊会降低背景图清晰度）。文字/气泡/代码各自携带半透明表面。 */\n\n/* -------------------------------------------------------------------------\n   输入栏：磨砂胶囊 + 聚焦光环（Cherry 特征）\n   注意：容器 [data-composer-seat] 不施加 backdrop-filter——拖拽遮罩\n   DropOverlay 与图片灯箱 ImageLightbox（均 fixed）渲染在容器内部。\n   ------------------------------------------------------------------------- */\n[data-composer-card] {\n    backdrop-filter: blur(16px) saturate(1.15);\n    -webkit-backdrop-filter: blur(16px) saturate(1.15);\n    transition:\n        border-color var(--cherry-glass-transition-duration) var(--cherry-glass-transition-easing),\n        box-shadow var(--cherry-glass-transition-duration) var(--cherry-glass-transition-easing);\n}\n\n/* 聚焦时：主题色描边 + 外发光（保留原有阴影层） */\n[data-composer-card]:focus-within {\n    border-color: var(--dsw-alias-brand-primary);\n    box-shadow:\n        var(--dsw-shadow-lv2),\n        0 0 0 3px color-mix(in srgb, var(--dsw-alias-brand-primary) 18%, transparent);\n}\n\n/* -------------------------------------------------------------------------\n   用户/steering 气泡：仅保留 DSH 原生半透明胶囊（--dsw-specific-bubble 令牌）。\n   v0.2/v0.3 曾试图叠加 Cherry 描边/装饰线/磨砂，但结构选择器下探层级不足，\n   实际命中\"用户栈\"长方形容器，产生违和的长方形毛玻璃边框——v0.4 已整组移除\n   （气泡元素本身是哈希类名，无稳定 data-* 接缝，不宜继续做结构装饰）。\n   ------------------------------------------------------------------------- */\n\n/* -------------------------------------------------------------------------\n   链接 / 选中文本\n   ------------------------------------------------------------------------- */\na {\n    color: var(--dsw-alias-brand-primary);\n}\n\n::selection {\n    background-color: color-mix(in srgb, var(--dsw-alias-brand-primary) 25%, transparent);\n}\n";
